script:
(function () {
  'use strict';
  // Six independent percentage forms, each recalculated live:
  //   1. P% of N            = P / 100 x N
  //   2. X is what % of Y   = X / Y x 100                     (Y = 0 -> error)
  //   3. X is P% of what    = X / (P / 100)                   (P = 0 -> error)
  //   4. % change A -> B    = (B - A) / |A| x 100             (A = 0 -> error; |A| keeps the sign
  //                                                           meaning "up"/"down" when A is negative)
  //   5. N increased/decreased by P% = N x (1 +/- P / 100)
  //   6. % difference A, B  = |A - B| / ((|A| + |B|) / 2) x 100 (both 0 -> error)
  // Results are tidied to 12 significant digits so float noise (0.1 + 0.2) never shows.
  // Verified (Node scratch test): 20% of 150 = 30; 30 is 20% of 150; 30 is 20% of 150 -> 150;
  // 80 -> 100 = +25%; 100 -> 80 = -20%; -50 -> -25 = +50%; 200 + 15% = 230; 200 - 15% = 170;
  // % difference 80 vs 100 = 22.2222%; 17.5% of 1234.56 = 216.048; division-by-zero cases show an error.
  var nf = new Intl.NumberFormat('en-US', { maximumFractionDigits: 6 });

  function num(id) {
    var s = String(document.getElementById(id).value).trim();
    if (s === '') return NaN;
    var v = Number(s);
    return isFinite(v) ? v : NaN;
  }
  function tidy(x) { var t = Number(x.toPrecision(12)); return t === 0 ? 0 : t; }
  function fmt(x) { return nf.format(tidy(x)); }
  function set(id, text) { document.getElementById(id).textContent = text; }

  function percentOf(p, n) { return p / 100 * n; }
  function whatPercent(part, whole) { return whole === 0 ? NaN : part / whole * 100; }
  function wholeFrom(part, p) { return p === 0 ? NaN : part / (p / 100); }
  function percentChange(from, to) { return from === 0 ? NaN : (to - from) / Math.abs(from) * 100; }
  function applyPercent(n, p, dir) { return n * (1 + dir * p / 100); }
  function percentDiff(a, b) {
    var mean = (Math.abs(a) + Math.abs(b)) / 2;
    return mean === 0 ? NaN : Math.abs(a - b) / mean * 100;
  }

  // Shows a section's answer, or its error message when msg is set.
  function show(k, msg, out, work) {
    var err = document.getElementById('pc' + k + 'Err');
    err.hidden = !msg;
    err.textContent = msg || '';
    set('pc' + k + 'Out', msg ? '–' : out);
    set('pc' + k + 'Work', msg ? '' : work);
  }
  function finite(x) { return typeof x === 'number' && isFinite(x); }
  var MISSING = 'Enter both numbers.';

  function s1() {
    var p = num('pc1P'), n = num('pc1N');
    if (isNaN(p) || isNaN(n)) return show(1, MISSING);
    var r = percentOf(p, n);
    if (!finite(r)) return show(1, 'That result is too large to show.');
    show(1, '', fmt(r), fmt(p) + ' ÷ 100 × ' + fmt(n) + ' = ' + fmt(r));
  }
  function s2() {
    var x = num('pc2X'), y = num('pc2Y');
    if (isNaN(x) || isNaN(y)) return show(2, MISSING);
    if (y === 0) return show(2, 'The second number can’t be 0, because dividing by 0 is undefined.');
    var r = whatPercent(x, y);
    if (!finite(r)) return show(2, 'That result is too large to show.');
    show(2, '', fmt(r) + '%', fmt(x) + ' ÷ ' + fmt(y) + ' × 100 = ' + fmt(r) + '%');
  }
  function s3() {
    var x = num('pc3X'), p = num('pc3P');
    if (isNaN(x) || isNaN(p)) return show(3, MISSING);
    if (p === 0) return show(3, 'The percent can’t be 0, because 0% of any number is 0.');
    var r = wholeFrom(x, p);
    if (!finite(r)) return show(3, 'That result is too large to show.');
    show(3, '', fmt(r), fmt(x) + ' ÷ (' + fmt(p) + ' ÷ 100) = ' + fmt(r));
  }
  function s4() {
    var a = num('pc4A'), b = num('pc4B');
    if (isNaN(a) || isNaN(b)) return show(4, MISSING);
    if (a === 0) { set('pc4Diff', '–'); set('pc4Label', 'Percent change');
      return show(4, 'A percent change can’t be measured from a starting value of 0.'); }
    var r = percentChange(a, b);
    if (!finite(r)) { set('pc4Diff', '–'); return show(4, 'That result is too large to show.'); }
    var t = tidy(r);
    set('pc4Label', t > 0 ? 'Percent increase' : t < 0 ? 'Percent decrease' : 'Percent change');
    set('pc4Diff', (tidy(b - a) > 0 ? '+' : '') + fmt(b - a));
    show(4, '', (t > 0 ? '+' : '') + fmt(r) + '%',
      '(' + fmt(b) + ' − ' + fmt(a) + ') ÷ ' + fmt(Math.abs(a)) + ' × 100 = ' + fmt(r) + '%');
  }
  function s5() {
    var n = num('pc5N'), p = num('pc5P');
    var dir = document.getElementById('pc5Dir').value === 'down' ? -1 : 1;
    if (isNaN(n) || isNaN(p)) { set('pc5Change', '–'); return show(5, MISSING); }
    var r = applyPercent(n, p, dir);
    if (!finite(r)) { set('pc5Change', '–'); return show(5, 'That result is too large to show.'); }
    set('pc5Change', (tidy(r - n) > 0 ? '+' : '') + fmt(r - n));
    show(5, '', fmt(r), fmt(n) + ' × (1 ' + (dir > 0 ? '+' : '−') + ' ' + fmt(p) + ' ÷ 100) = ' + fmt(r));
  }
  function s6() {
    var a = num('pc6A'), b = num('pc6B');
    if (isNaN(a) || isNaN(b)) return show(6, MISSING);
    var r = percentDiff(a, b);
    if (isNaN(r)) return show(6, 'At least one value must be non-zero.');
    if (!finite(r)) return show(6, 'That result is too large to show.');
    show(6, '', fmt(r) + '%', '|' + fmt(a) + ' − ' + fmt(b) + '| ÷ ((' + fmt(Math.abs(a)) + ' + ' +
      fmt(Math.abs(b)) + ') ÷ 2) × 100 = ' + fmt(r) + '%');
  }

  var sections = [s1, s2, s3, s4, s5, s6];

  document.addEventListener('DOMContentLoaded', function () {
    sections.forEach(function (fn, i) {
      var form = document.getElementById('pcForm' + (i + 1));
      if (!form) return;
      form.addEventListener('input', fn);
      form.addEventListener('change', fn);
      form.addEventListener('submit', function (e) { e.preventDefault(); });
      fn();
    });
  });
})();
